/*---
description: NFKD agrees with Node for every code point U+070000 through U+07FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [1232984517, 782318021, 2695573957, 721269189, 2879472069, 188189125, 3511513541, 1056057797, 2530136517, 164080069, 863816133, 2549244357, 4193227205, 3345723845, 879182277, 835807685];
const blocks = ["NFKD U+070000-U+070FFF", "NFKD U+071000-U+071FFF", "NFKD U+072000-U+072FFF", "NFKD U+073000-U+073FFF", "NFKD U+074000-U+074FFF", "NFKD U+075000-U+075FFF", "NFKD U+076000-U+076FFF", "NFKD U+077000-U+077FFF", "NFKD U+078000-U+078FFF", "NFKD U+079000-U+079FFF", "NFKD U+07A000-U+07AFFF", "NFKD U+07B000-U+07BFFF", "NFKD U+07C000-U+07CFFF", "NFKD U+07D000-U+07DFFF", "NFKD U+07E000-U+07EFFF", "NFKD U+07F000-U+07FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 458752 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
